// The page is assembled here rather than in a template node: one place to
// read, and the shape of each system's response is documented by the code
// that unpicks it.

const meetings = ($('Upcoming bookings').first().json.list) || [];
const invoices = ($('Awaiting payment').first().json.Invoices) || [];
const balance  = $('Stripe balance').first().json || {};

const money = (n) => '£' + Number(n || 0).toFixed(2);

// Everything below came from outside this system. A customer's name is user
// input like any other, and it is going into HTML.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const when = (raw) => {
  if (!raw) return '';
  const iso = String(raw).replace(' ', 'T');
  const d = new Date(iso.endsWith('Z') ? iso : iso + 'Z');
  return isNaN(d) ? '' : d.toLocaleString('en-GB', { weekday: 'short', day: 'numeric',
    month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' });
};

// Stripe reports minor units, per currency.
const sum = (arr) => (arr || []).reduce((t, b) => t + (b.amount || 0), 0) / 100;

const bookingRows = meetings.length
  ? meetings.map(m => `<tr><td>${esc(when(m.dateStart))}</td><td>${esc(m.name)}</td>` +
      `<td>${esc(m.status)}</td></tr>`).join('')
  : '<tr><td colspan="3" class="quiet">Nothing booked.</td></tr>';

const unpaidRows = invoices.length
  ? invoices.map(i => `<tr><td>${esc(i.InvoiceNumber)}</td>` +
      `<td>${esc(i.Contact && i.Contact.Name)}</td>` +
      `<td>${money(i.AmountDue)}</td></tr>`).join('')
  : '<tr><td colspan="3" class="quiet">Everything is paid.</td></tr>';

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<title>IT Surgery — Dashboard</title>
<style>
 :root{--brand:#990000;--ink:#222;--quiet:#5a6068;--line:#dcdfe3;--bg:#f4f5f7}
 *{box-sizing:border-box}
 body{margin:0;background:var(--bg);color:var(--ink);
   font:16px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif}
 header{background:var(--brand);color:#fff;padding:1rem 1.25rem}
 header h1{margin:0;font-size:1.15rem}
 header p{margin:.25rem 0 0;opacity:.85;font-size:.85rem}
 main{padding:1rem;max-width:900px;margin:0 auto}
 .card{background:#fff;border:1px solid var(--line);border-radius:8px;padding:1rem;margin-bottom:1rem}
 .card h2{margin:0 0 .75rem;font-size:.85rem;text-transform:uppercase;letter-spacing:.05em;color:var(--quiet)}
 .figs{display:flex;gap:2rem;flex-wrap:wrap}
 .fig strong{display:block;font-size:1.75rem;line-height:1.2}
 .fig span{font-size:.8rem;color:var(--quiet)}
 table{width:100%;border-collapse:collapse}
 td,th{text-align:left;padding:.45rem 0;border-bottom:1px solid var(--line);font-size:.92rem}
 th{font-size:.75rem;text-transform:uppercase;letter-spacing:.04em;color:var(--quiet)}
 tr:last-child td{border-bottom:0}
 .quiet{color:var(--quiet)}
</style></head><body>
<header><h1>IT Surgery</h1><p>${esc(when(new Date().toISOString()))}</p></header>
<main>
  <div class="card"><h2>Money</h2><div class="figs">
    <div class="fig"><strong>${money(sum(balance.available))}</strong><span>available in Stripe</span></div>
    <div class="fig"><strong>${money(sum(balance.pending))}</strong><span>pending</span></div>
    <div class="fig"><strong>${invoices.length}</strong><span>awaiting payment</span></div>
  </div></div>
  <div class="card"><h2>Coming up</h2>
    <table><tr><th>When</th><th>What</th><th>Status</th></tr>${bookingRows}</table></div>
  <div class="card"><h2>Awaiting payment</h2>
    <table><tr><th>Invoice</th><th>Who</th><th>Due</th></tr>${unpaidRows}</table></div>
</main></body></html>`;

return [{ json: { html } }];
